// Original pixel-art animation frames, authored in code and cached per creature.
import {COLORS} from './engine.js';
export const FRAMES=8,DIRECTIONS=['south','east','north','west'];
const cache=new Map(),portraits=new Map();
export function creatureKind(e){const n=e.name||'';if(/tank|wagon|demolisher|thrower|contraption/i.test(n))return 'machine';if(/battleship/i.test(n))return 'ship';if(/owl|albatross|harpy|batrider|phoenix/i.test(n))return 'bird';if(/dragon|drake/i.test(n))return 'dragon';if(/arachnid|spider|makrura/i.test(n))return 'spider';if(/worm/i.test(n))return 'worm';if(/naga/i.test(n))return 'naga';if(/wolf|beast|raccoon|rat|lizard|hydra|centaur|keeper of the grove/i.test(n))return 'beast';if(/golem|giant|treant|shredder|wildkin|stalker|magnataur|tauren|furbolg|pandaren/i.test(n))return 'heavy';if(/sludge|watery|living waters|lava runner/i.test(n))return 'slime';if(/wisp|ghost|spirit of vengeance|void walker|living flame|firelord|fire revenant|sea revenant/i.test(n))return 'spirit';return 'humanoid';}
export function movementFrame(e){return Math.floor((e.walkDistance||0)/(creatureKind(e)==='heavy'?48:creatureKind(e)==='machine'?26:34))%FRAMES;}
function palette(e){const color=COLORS[e.element]||'#bbc6c3',n=e.name||'';return {color,edge:'#101d21',dark:e.element==='fire'?'#6a322a':e.element==='nature'?'#345331':e.element==='water'?'#285264':e.element==='darkness'?'#403050':'#5a5349',light:e.element==='darkness'?'#d8b3fa':e.element==='water'?'#c6f6f5':'#f1dfb4',skin:/ghoul|satyr|troll|goblin|kobold|child|bandit/i.test(n)?color:'#b5a087',metal:/knight|paladin|guard|protector|admiral|tank|clockwerk|shredder/i.test(n)?'#b7c4c4':color};}
function frame(c,e,kind,dir,index){const p=palette(e),a=index*Math.PI/4,step=Math.sin(a),opposite=Math.sin(a+Math.PI),back=dir==='north',side=dir==='east'||dir==='west',n=e.name||'';c.save();if(dir==='west'){c.translate(48,0);c.scale(-1,1);}const rect=(x,y,w,h,color)=>{c.fillStyle=color;c.fillRect(Math.round(x),Math.round(y),w,h);},poly=(points,color)=>{c.fillStyle=color;c.beginPath();points.forEach(([x,y],i)=>i?c.lineTo(Math.round(x),Math.round(y)):c.moveTo(Math.round(x),Math.round(y)));c.closePath();c.fill();},limb=(x,y,tx,ty,w,color)=>{const dx=tx-x,dy=ty-y,len=Math.hypot(dx,dy)||1,ox=-dy/len*w/2,oy=dx/len*w/2;poly([[x+ox,y+oy],[tx+ox,ty+oy],[tx-ox,ty-oy],[x-ox,y-oy]],p.edge);poly([[x+ox*.65,y+oy*.65],[tx+ox*.65,ty+oy*.65],[tx-ox*.65,ty-oy*.65],[x-ox*.65,y-oy*.65]],color);},eyes=(x,y)=>{if(back)return;rect(x,y,side?2:3,2,p.light);if(!side)rect(x+6,y,3,2,p.light);};
 if(kind==='humanoid'||kind==='heavy'){const heavy=kind==='heavy',w=heavy?22:16,bob=Math.abs(step)*(heavy?1:2),cx=24,head=12-bob,hip=30-bob;
 limb(cx-5,hip,cx-6+step*3,41,heavy?7:5,p.dark);limb(cx+5,hip,cx+6+opposite*3,41,heavy?7:5,p.dark);rect(cx-10+step*3,40,8,3,p.edge);rect(cx+2+opposite*3,40,8,3,p.edge);
 rect(cx-w/2-1,head+9,w+2,15,p.edge);rect(cx-w/2,head+10,w,12,p.metal);rect(cx-w/2+2,head+11,w-4,3,p.light);rect(cx-w/2,head+20,w,3,p.dark);
 const swing=step*4;limb(cx-w/2-1,head+11,cx-w/2-3,head+24+swing,heavy?7:4,p.color);limb(cx+w/2+1,head+11,cx+w/2+3,head+24-swing,heavy?7:4,p.color);
 rect(cx-7,head,14,11,p.edge);rect(cx-6,head+1,12,8,p.skin);rect(cx-6,head-2,12,4,p.dark);eyes(cx+(side?1:-4),head+5);
 if(/treant|keeper|stalker/i.test(n)){limb(19,head,13,head-5,3,p.dark);limb(29,head,35,head-5,3,p.dark);rect(11,head-8,7,5,p.color);rect(31,head-8,7,5,p.color);}
 else if(/tauren|magnataur|doom|pit lord|satyr/i.test(n)){poly([[17,head],[12,head-6],[14,head+3]],p.light);poly([[31,head],[36,head-6],[34,head+3]],p.light);}
 else if(/knight|paladin|guard|protector|revenant/i.test(n)){rect(16,head-3,16,5,p.metal);rect(23,head-7,3,5,p.color);if(!back)rect(21,head+4,6,4,p.edge);}
 if(!heavy){const weaponX=side?35:34,wy=head+14-swing;rect(weaponX,wy,2,17,p.dark);if(/priest|archmage|elf|succubus/i.test(n)){rect(weaponX-2,wy-3,6,5,p.color);rect(weaponX,wy-2,2,2,p.light);}else{rect(weaponX-1,wy-7,4,12,p.light);rect(weaponX-3,wy+5,8,2,p.dark);}}
 if(back)rect(19,head+11,10,10,p.dark);
 }else if(kind==='beast'||kind==='dragon'){const flying=kind==='dragon',bob=flying?Math.sin(a)*2:Math.abs(step),bodyY=24-bob;for(let leg=0;leg<4;leg++){const x=side?13+leg*6:17+(leg%2)*13,y=bodyY+(leg<2?3:8),phase=Math.sin(a+(leg%2?Math.PI:0));limb(x,y,x+phase*4,y+10,4,p.dark);rect(x+phase*4-2,y+8,5,3,p.edge);}
 poly([[10,bodyY-8],[33,bodyY-8],[38,bodyY+6],[13,bodyY+7]],p.edge);rect(12,bodyY-7,23,12,p.color);rect(14,bodyY-6,18,3,p.light);
 const hx=side?33:back?24:24,hy=side?bodyY-5:back?bodyY-15:bodyY+2;rect(hx-6,hy-5,13,11,p.edge);rect(hx-5,hy-4,11,8,p.color);rect(hx+(side?4:-3),hy+2,side?7:7,4,p.dark);eyes(hx+(side?1:-4),hy-1);poly([[hx-5,hy-3],[hx-7,hy-11],[hx-1,hy-5]],p.dark);poly([[hx+4,hy-3],[hx+7,hy-11],[hx+1,hy-5]],p.dark);
 limb(12,bodyY,5,bodyY-3+step*3,4,p.dark);if(flying){const reach=12+step*5;poly([[21,bodyY-5],[5,bodyY-reach],[8,bodyY+2],[20,bodyY+3]],p.dark);poly([[27,bodyY-5],[43,bodyY-reach],[40,bodyY+2],[28,bodyY+3]],p.color);}
 if(/hydra/i.test(n)){for(const x of [12,35]){limb(x,bodyY,x,bodyY-12+step*2,4,p.color);rect(x-4,bodyY-18+step*2,9,7,p.dark);if(!back)rect(x+1,bodyY-16+step*2,2,2,p.light);}}
 if(/centaur|keeper/i.test(n)){rect(24,bodyY-19,8,15,p.color);rect(23,bodyY-26,10,9,p.skin);eyes(24,bodyY-22);}
 }else if(kind==='bird'){const y=24+Math.sin(a)*2,reach=13+Math.sin(a)*8;poly([[21,y],[3,y-reach],[7,y+5],[22,y+8]],p.dark);poly([[27,y],[45,y-reach],[41,y+5],[26,y+8]],p.color);rect(19,y-6,10,16,p.edge);rect(20,y-5,8,14,p.color);rect(20,y-12,9,9,p.color);eyes(21,y-8);poly([[side?29:23,y-5],[side?35:26,y-3],[side?29:23,y-1]],'#d8a75d');poly([[20,y+8],[17,y+17],[24,y+13],[30,y+17],[28,y+8]],p.dark);if(/phoenix/i.test(n))rect(22,y+14,3,6,p.light);
 }else if(kind==='spider'){for(let i=0;i<4;i++)for(const sign of [-1,1]){const y=17+i*4,wiggle=Math.sin(a+i)*3;limb(24+sign*6,y,24+sign*(15+wiggle),y-5,3,p.dark);limb(24+sign*(15+wiggle),y-5,24+sign*19,y+5+wiggle,2,p.color);}rect(16,15,16,19,p.edge);rect(18,16,12,16,p.color);rect(20,18,8,5,p.light);rect(19,12,10,8,p.dark);eyes(20,15);
 }else if(kind==='machine'||kind==='ship'){const y=23+(kind==='ship'?Math.sin(a):0);rect(9,y-7,30,18,p.edge);rect(11,y-6,26,14,p.metal);rect(14,y-5,18,4,p.light);if(kind==='ship'){poly([[8,y+1],[3,y-3],[10,y+10],[37,y+10],[43,y-3],[37,y+1]],p.dark);rect(23,y-20,2,18,p.dark);poly([[25,y-19],[38,y-9],[25,y-7]],p.light);if(!side){rect(12,back?y-5:y+7,25,2,p.light);}}else{for(const ty of [y-9,y+10]){rect(8,ty,32,5,p.dark);for(let i=0;i<5;i++)rect(9+i*6+(index%2),ty+1,3,2,p.light);}rect(19,y-10,12,9,p.dark);if(side)rect(28,y-8,14,3,p.metal);else rect(22,back?y-20:y-1,4,12,p.metal);}
 }else if(kind==='worm'||kind==='naga'){for(let i=5;i>=0;i--){const x=24+Math.sin(a-i*.6)*5,y=16+i*4;rect(x-6,y-3,13,7,p.edge);rect(x-5,y-2,11,5,p.color);rect(x-3,y-2,5,1,p.light);}if(kind==='naga'){rect(18,9,13,14,p.color);rect(19,2,11,10,p.dark);eyes(20,7);limb(18,15,10+step*2,24,4,p.color);limb(31,15,38-step*2,23,4,p.color);}else{rect(19,12,10,4,p.edge);eyes(19,9);}
 }else if(kind==='slime'){const h=17+Math.sin(a)*3,w=25-Math.sin(a)*4,y=40-h;poly([[24-w/2,39],[24-w/2-2,y+7],[20,y],[28,y],[24+w/2+2,y+7],[24+w/2,39]],p.edge);poly([[24-w/2+1,37],[24-w/2,y+8],[20,y+2],[28,y+2],[24+w/2,y+8],[24+w/2-1,37]],p.color);rect(18,y+5,4,2,p.light);eyes(19,y+10);
 }else{const y=20+Math.sin(a)*2;for(let i=0;i<5;i++){const x=14+i*5;poly([[x-3,y+14],[x+Math.sin(a+i)*4,y-10-(i%2)*6],[x+4,y+14]],i%2?p.color:p.dark);}rect(18,y-1,12,10,p.color);eyes(20,y+2);for(let i=0;i<3;i++)rect(12+i*10+Math.sin(a+i)*3,y+18+i%2*3,3,3,p.light);}
 c.restore();}
export function creatureAtlas(e){const key=[e.name,e.element,e.tier||1].join('|');if(cache.has(key))return cache.get(key);const canvas=document.createElement('canvas');canvas.width=48*FRAMES;canvas.height=48*4;const c=canvas.getContext('2d'),kind=creatureKind(e);c.imageSmoothingEnabled=false;for(let dir=0;dir<4;dir++)for(let i=0;i<FRAMES;i++){c.save();c.translate(i*48,dir*48);c.beginPath();c.rect(0,0,48,48);c.clip();frame(c,e,kind,DIRECTIONS[dir],i);c.restore();}cache.set(key,canvas);if(cache.size>24)cache.delete(cache.keys().next().value);return canvas;}
export function creaturePortrait(e){const key=[e.name,e.element,e.tier||1].join('|');if(portraits.has(key))return portraits.get(key);const canvas=document.createElement('canvas');canvas.width=48;canvas.height=48;canvas.getContext('2d').drawImage(creatureAtlas(e),0,0,48,48,0,0,48,48);const url=canvas.toDataURL();portraits.set(key,url);return url;}
export function drawWalkingCreature(c,e,x,y,size){const dir=Math.max(0,DIRECTIONS.indexOf(e.facing||'south')),index=e.resurrecting>0?0:movementFrame(e);c.drawImage(creatureAtlas(e),index*48,dir*48,48,48,x-size/2,y-size*.7,size,size);}
